> library(survival)
> library(gt)
> tidy_aft <- function(m, drop = "Log\\(scale\\)|SCHOOL_Name") {
>   tb <- summary(m)$table
>   se_col <- grep("Std", colnames(tb), value = TRUE)[1]   # robuste si robust=TRUE
>   recode_terms <- c(
>     "(Intercept)"="(Intercept)", "year_c"="Year (from 2004)",
>     "GRADE2-CE1"="Grade CE1","GRADE3-CE2"="Grade CE2",
>     "GRADE4-CM1"="Grade CM1","GRADE5-CM2"="Grade CM2",
>     "SEXM"="Sex (male)","SCHOOL_IPS2025"="School IPS"
>   )
>   tibble::tibble(
>     term = rownames(tb), est = tb[, "Value"], se = tb[, se_col],
>     z = tb[, "z"], p = tb[, "p"]
>   ) |>
>     dplyr::filter(!grepl(drop, term)) |>
>     dplyr::transmute(
>       Term        = dplyr::recode(term, !!!recode_terms),
>       `Time ratio`= round(exp(est), 3),
>       lower.CL    = round(exp(est - 1.96 * se), 3),
>       upper.CL    = round(exp(est + 1.96 * se), 3),
>       z           = round(z, 2),
>       p           = ifelse(p < .001, "<.001", formatC(p, format = "f", digits = 3))
>     )
> }
> m1_TL <- survreg(
>   Surv(TL, finisher) ~ year_c + GRADE + SEX + SCHOOL_IPS2025 + cluster(SCHOOL_Name),
>   dist = "lognormal", data = df, robust = TRUE
> )
> tidy_aft(m1_TL) |>
>   gt() |>
>   tab_header(
>     title    = "TL — main AFT model (lognormal), cluster-robust SEs",
>     subtitle = "Time ratios; TR < 1 = shorter reading time over time"
>   ) |>
>   tab_options(table.font.size = px(12))
