> make_period2 <- function(year) {
>   factor(ifelse(year >= 2018, "2018–2025", "2004–2017"),
>          levels = c("2004–2017", "2018–2025"))
> }
> df <- df %>%
>   dplyr::mutate(
>     year_c        = YEAR - 2004,
>     year_post2018 = pmax(YEAR - 2018, 0),
>     period2       = make_period2(YEAR)
>   )
> m_lin_TL  <- survreg(Surv(TL, finisher) ~ year_c + GRADE + SEX + SCHOOL_IPS2025,
>                      dist = "lognormal", data = df)
> m_step_TL <- survreg(Surv(TL, finisher) ~ period2 + GRADE + SEX + SCHOOL_IPS2025,
>                      dist = "lognormal", data = df)
> m_seg_TL  <- survreg(Surv(TL, finisher) ~ year_c + year_post2018 + GRADE + SEX + SCHOOL_IPS2025,
>                      dist = "lognormal", data = df)
> mods_TL <- list(Linear = m_lin_TL, `Step 2018` = m_step_TL, Segmented = m_seg_TL)
> tibble::tibble(
>   Model = names(mods_TL),
