>   GRADE = factor(levels(df$GRADE), levels = levels(df$GRADE))
> ) %>%
>   dplyr::mutate(
>     year_c         = YEAR - 2004,
>     year_post2018  = pmax(YEAR - 2018, 0),
>     period2        = make_period2(YEAR),
>     SEX            = factor(levels(df$SEX)[1], levels = levels(df$SEX)),
>     SCHOOL_IPS2025 = mean(df$SCHOOL_IPS2025, na.rm = TRUE)
>   )
> grid_TL$Linear      <- pfin(m_lin_TL,  grid_TL)
> grid_TL$`Step 2018` <- pfin(m_step_TL, grid_TL)
> grid_TL$Segmented   <- pfin(m_seg_TL,  grid_TL)
> pred_long_TL <- grid_TL %>%
>   dplyr::select(YEAR, GRADE, Linear, `Step 2018`, Segmented) %>%
>   tidyr::pivot_longer(c(Linear, `Step 2018`, Segmented),
>                       names_to = "Model", values_to = "p_finish")
> obs_fin <- df %>%
>   dplyr::group_by(GRADE, YEAR) %>%
>   dplyr::summarise(p_finish = mean(finisher), n = dplyr::n(), .groups = "drop")
> ggplot() +
>   geom_point(data = obs_fin, aes(YEAR, p_finish, size = n),
>              alpha = 0.35, colour = "grey30") +
>   geom_line(data = pred_long_TL, aes(YEAR, p_finish, colour = Model),
>             linewidth = 0.8) +
>   facet_wrap(~ GRADE, scales = "free_y") +
>   scale_size_continuous(range = c(1, 5), guide = "none") +
>   labs(x = "Year", y = "P(finish within 180 s)", colour = NULL) +
>   theme_Publication()
> df <- df %>%
>   dplyr::mutate(
>     year_c        = YEAR - 2004,
>     post2018      = factor(ifelse(YEAR >= 2018, "Post-2018", "Pre-2018"),
>                            levels = c("Pre-2018", "Post-2018")),
>     year_post2018 = pmax(YEAR - 2018, 0)
>   )
> m_its_TL <- survreg(
>   Surv(TL, finisher) ~ year_c + post2018 + year_post2018 +
